arguments.command:
python -c "
import more_itertools as mi

# Check that all required names are exported
required = ['sliced', 'split_at', 'split_before', 'split_after', 'split_when', 
            'zip_equal', 'UnequalIterablesError', 'stagger']

for name in required:
    if hasattr(mi, name):
        print(f'{name}: OK')
    else:
        print(f'{name}: MISSING!')

# Also check __all__
print()
print('In __all__:')
for name in required:
    if name in mi.__all__:
        print(f'  {name}: YES')
    else:
        print(f'  {name}: NO')
"
